head.b:skin:
/*
-----------------------------------------------
  InLumine — plantilla editorial para Blogger
  Los colores y tipografias se cambian abajo,
  en el bloque :root
-----------------------------------------------
*/

:root{
  --bg:#faf9f7;
  --surface:#ffffff;
  --ink:#14130f;
  --muted:#6f6a61;
  --line:#e7e2d9;
  --accent:#b8893f;
  --dark:#15140f;
  --serif:'Cormorant Garamond',Georgia,'Times New Roman',serif;
  --sans:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
  --shell:1180px;
}

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.65;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{margin:0}
.shell{max-width:var(--shell);margin:0 auto;padding:0 28px}
.eyebrow{display:flex;align-items:center;gap:14px;font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--accent);margin:0 0 14px}
.eyebrow::before{content:'';display:block;width:42px;height:1px;background:var(--accent);flex:none}

/* ---------- Cabecera ---------- */
.site-header{background:var(--surface);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:60}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:74px}
.brand-mark{font-family:var(--serif);font-size:27px;font-weight:600;letter-spacing:.005em;line-height:1;white-space:nowrap}
.brand-a{color:var(--ink)}
.brand-b{color:var(--accent)}
.topnav{display:flex;gap:26px;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none}
.topnav::-webkit-scrollbar{display:none}
.topnav-link{font-size:11.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);white-space:nowrap;padding:5px 0;border-bottom:1px solid transparent;transition:color .2s,border-color .2s}
.topnav-link:hover{color:var(--ink);border-bottom-color:var(--accent)}

/* ---------- Portada ---------- */
.masthead{background:var(--surface);border-bottom:1px solid var(--line);padding:68px 0 54px}
.masthead-inner{max-width:var(--shell);margin:0 auto;padding:0 28px;display:flex;justify-content:space-between;align-items:flex-end;gap:44px;flex-wrap:wrap}
.masthead-title{font-family:var(--serif);font-size:clamp(54px,9vw,104px);line-height:.92;font-weight:400;letter-spacing:-.022em}
.masthead-tags{text-align:right;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);line-height:2.1}
.masthead-star{color:var(--accent);font-size:20px;line-height:1;margin-bottom:10px}

/* ---------- Barra de secciones ---------- */
.sections-bar{background:var(--surface);border-bottom:1px solid var(--line)}
.sections{display:flex;align-items:center;gap:26px;max-width:var(--shell);margin:0 auto;padding:15px 28px;overflow-x:auto;scrollbar-width:none}
.sections::-webkit-scrollbar{display:none}
.sections-label{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--accent);padding-right:26px;border-right:1px solid var(--line);white-space:nowrap;flex:none}
.section-link{font-size:11.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);white-space:nowrap;transition:color .2s}
.section-link:hover{color:var(--accent)}
.section-count{color:var(--line);margin-left:5px;font-size:10px}

/* ---------- Encabezado de listados ---------- */
.listing-head{padding:56px 0 0}
.listing-title{font-family:var(--serif);font-size:clamp(34px,5vw,52px);font-weight:400;line-height:1.05;letter-spacing:-.015em}
.listing-note{color:var(--muted);font-size:13px;margin-top:12px}

/* ---------- Rejilla de entradas ---------- */
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:48px 34px;padding:60px 0}
.grid{counter-reset:cards}
.card{display:flex;flex-direction:column;counter-increment:cards}
.card-index::before{content:counter(cards,decimal-leading-zero)}
.card-lead{grid-column:1 / -1;display:grid;grid-template-columns:1.12fr 1fr;gap:46px;align-items:center;padding-bottom:48px;border-bottom:1px solid var(--line)}
.card-media{position:relative;overflow:hidden;background:#efece6;aspect-ratio:16/10;margin-bottom:18px}
.card-lead .card-media{margin-bottom:0;aspect-ratio:4/3}
.card-media img{width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.7,.3,1)}
.card:hover .card-media img{transform:scale(1.045)}
.card-media-empty{display:flex;align-items:center;justify-content:center;font-family:var(--serif);font-size:44px;color:#d8d2c7}

/* fila de datos */
.card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:9px;font-size:10.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);margin-bottom:11px}
.card-meta .sep{width:3px;height:3px;border-radius:50%;background:#d5cfc4;flex:none}
.card-label{color:var(--accent)}
.card-index{font-family:var(--serif);font-size:13px;color:var(--accent);letter-spacing:.05em}
.card-title{font-family:var(--serif);font-size:26px;line-height:1.2;font-weight:500;margin-bottom:10px;letter-spacing:-.005em}
.card-lead .card-title{font-size:clamp(32px,4vw,46px);line-height:1.08;font-weight:400}
.card:hover .card-title{color:var(--accent)}
.card-snippet{color:var(--muted);font-size:15px;margin-bottom:16px}
.card-lead .card-snippet{font-size:17px}
.card-more{align-self:flex-start;margin-top:auto;font-size:10.5px;letter-spacing:.17em;text-transform:uppercase;color:var(--ink);border-bottom:1px solid var(--accent);padding-bottom:3px}
.empty{padding:90px 0;text-align:center;color:var(--muted);font-family:var(--serif);font-size:22px}

/* ---------- Entrada individual ---------- */
.entry{max-width:768px;margin:0 auto;padding:70px 0 40px}
.entry-title{font-family:var(--serif);font-size:clamp(36px,6vw,60px);line-height:1.06;font-weight:400;letter-spacing:-.014em;margin-bottom:22px}
.entry-meta{display:flex;flex-wrap:wrap;align-items:center;gap:10px;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding-bottom:26px;border-bottom:1px solid var(--line);margin-bottom:38px}
.entry-hero{margin:0 0 38px;background:#efece6}
.entry-body{font-family:var(--serif);font-size:20px;line-height:1.78}
.entry-body p{margin:0 0 1.35em}
.entry-body h2{font-family:var(--serif);font-size:32px;font-weight:500;margin:1.6em 0 .5em;line-height:1.2}
.entry-body h3{font-family:var(--serif);font-size:25px;font-weight:500;margin:1.5em 0 .45em}
.entry-body img{margin:2.2em auto}
.entry-body ul,.entry-body ol{margin:0 0 1.35em;padding-left:1.3em}
.entry-body li{margin-bottom:.45em}
.entry-body blockquote{margin:2em 0;padding:0 0 0 26px;border-left:2px solid var(--accent);font-style:italic;color:var(--muted)}
.entry-body a{color:var(--accent);border-bottom:1px solid rgba(184,137,63,.35)}
.entry-labels{display:flex;flex-wrap:wrap;gap:9px;margin:46px 0 0;padding-top:30px;border-top:1px solid var(--line)}
.entry-label{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);border:1px solid var(--line);padding:7px 14px;transition:border-color .2s,color .2s}
.entry-label:hover{color:var(--accent);border-color:var(--accent)}

/* ---------- Paginador y comentarios ---------- */
.blog-pager{display:flex;justify-content:space-between;align-items:center;gap:20px;max-width:var(--shell);margin:0 auto;padding:30px 0 76px;border-top:1px solid var(--line);font-size:11px;letter-spacing:.15em;text-transform:uppercase}
.blog-pager a{color:var(--muted)}
.blog-pager a:hover{color:var(--accent)}
#blog-pager-newer-link,#blog-pager-older-link{flex:1}
#blog-pager-older-link{text-align:right}
.comments{max-width:768px;margin:0 auto;padding:20px 0 80px}
.comments h4{font-family:var(--serif);font-size:24px;font-weight:500;margin-bottom:18px}
.comments .comment-actions,.comments .continue{margin-top:16px}

/* ---------- Pie ---------- */
.site-footer{background:var(--dark);color:#cbc5b8;margin-top:20px;padding:64px 0 44px}
.footer-inner{display:flex;justify-content:space-between;gap:38px;flex-wrap:wrap}
.footer-brand .brand-mark{font-size:25px}
.footer-brand .brand-a{color:#f4f1ea}
.footer-sub{font-size:12.5px;color:#8d867a;margin-top:8px}
.footer-right{font-size:12.5px;color:#8d867a;text-align:right}
.site-footer .widget{margin-bottom:18px}
.site-footer a{color:#cbc5b8}
.site-footer a:hover{color:var(--accent)}

/* ---------- Responsive ---------- */
@media (max-width:900px){
  .grid{grid-template-columns:repeat(2,1fr);gap:42px 28px}
  .card-lead{grid-template-columns:1fr;gap:26px}
  .card-lead .card-media{aspect-ratio:16/10}
}
@media (max-width:620px){
  .shell{padding:0 20px}
  .grid{grid-template-columns:1fr;gap:40px;padding:44px 0}
  .masthead{padding:44px 0 34px}
  .masthead-inner{padding:0 20px}
  .masthead-tags{text-align:left}
  .entry{padding:46px 0 30px}
  .entry-body{font-size:18.5px}
  .header-inner{min-height:64px}
  .sections{padding:13px 20px}
}

body.script:
//
(function(){
  var body = document.querySelector('.entry-body');
  var slot = document.querySelector('.js-readtime');
  if (!body || !slot) return;
  var words = (body.innerText || body.textContent || '').trim().split(/\s+/).length;
  var mins = Math.max(1, Math.round(words / 200));
  slot.textContent = mins + ' min de lectura';
})();
//
